package com.backend.nutri_predic.datasetmodelov6.controller;
import com.backend.nutri_predic.datasetmodelov6.dto.*; import com.backend.nutri_predic.datasetmodelov6.service.*; import java.nio.charset.StandardCharsets; import java.time.LocalDate; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/ml/dataset/v6") public class DatasetModeloV6Controller {private final DatasetModeloV6Service dataset;private final PreparacionDatasetModeloV6Service preparacion;private final EstadoPreparacionClienteV6Service estado;private final PendientesEntrenamientoV6Service pendientes;private final DatasetModeloV6TechnicalService technical;public DatasetModeloV6Controller(DatasetModeloV6Service d,PreparacionDatasetModeloV6Service p,EstadoPreparacionClienteV6Service e,PendientesEntrenamientoV6Service x,DatasetModeloV6TechnicalService t){dataset=d;preparacion=p;estado=e;pendientes=x;technical=t;}@GetMapping(value="/export",produces="text/csv") public ResponseEntity<byte[]> exportar(){return ResponseEntity.ok().contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=dataset-modelo-v6.csv").body(dataset.csv().getBytes(StandardCharsets.UTF_8));}@GetMapping(value="/technical-export",produces="text/csv") public ResponseEntity<byte[]> exportarTecnico(){return ResponseEntity.ok().contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=dataset-nutripredict-v6-technical.csv").body(technical.csv().getBytes(StandardCharsets.UTF_8));}@GetMapping("/calidad") public CalidadDatasetModeloV6Response calidad(){return dataset.calidad();}@GetMapping("/preparacion") public PreparacionDatasetModeloV6Response preparacion(){return preparacion.auditar();}@GetMapping("/clientes/{clienteId}/estado") public EstadoPreparacionClienteV6Response estado(@PathVariable Long clienteId,@RequestParam LocalDate fechaCorte){return estado.estado(clienteId,fechaCorte);}@GetMapping("/pendientes") public PendientesEntrenamientoV6Response pendientes(@RequestParam LocalDate fechaCorte){return pendientes.listar(fechaCorte);}}
